using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
public static class Native49RuntimeRendererAudit {
 static string H(Transform t)=>t.parent==null?t.name:H(t.parent)+"/"+t.name;
 static JObject Mat(Material m){if(m==null)return new JObject{["null"]=true};var messages=m.shader==null?new JArray():new JArray(ShaderUtil.GetShaderMessages(m.shader).Where(x=>x.severity.ToString()=="Error").Select(x=>x.message));var colors=new JObject();foreach(var n in new[]{"_Color","_BaseColor","_EmissionColor","_TintColor"})if(m.HasProperty(n)){var c=m.GetColor(n);colors[n]=new JArray(c.r,c.g,c.b,c.a);}return new JObject{["name"]=m.name,["path"]=AssetDatabase.GetAssetPath(m),["shader"]=m.shader?.name,["supported"]=m.shader!=null&&m.shader.isSupported,["errors"]=messages,["queue"]=m.renderQueue,["colors"]=colors,["keywords"]=new JArray(m.shaderKeywords)};}
 public static string Inspect(){if(!EditorApplication.isPlaying)throw new Exception("ActualPlayrequired");var rows=new JArray(UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsInactive.Exclude).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).Select(r=>new JObject{["hierarchy"]=H(r.transform),["type"]=r.GetType().FullName,["materials"]=new JArray(r.sharedMaterials.Select(Mat)),["trailMaterial"]=r is ParticleSystemRenderer ps?Mat(ps.trailMaterial):null}));var mats=rows.SelectMany(r=>((JArray)r["materials"]).Concat(r["trailMaterial"] is JObject t?new[]{t}:new JToken[0])).OfType<JObject>().ToArray();var report=new JObject{["utc"]=DateTime.UtcNow.ToString("o"),["pid"]=System.Diagnostics.Process.GetCurrentProcess().Id,["time"]=Time.time,["gameTime"]=UnityEngine.Object.FindObjectsByType<AppController>(FindObjectsInactive.Exclude).Single().CurrentTime,["rows"]=rows,["failed"]=new JArray(mats.Where(m=>m["null"]==null&&(!(bool)m["supported"]||((JArray)m["errors"]).Count!=0))),["softParticlesGlobal"]=Shader.IsKeywordEnabled("SOFTPARTICLES_ON"),["pipeline"]=GraphicsSettings.currentRenderPipeline?.name,["limits"]="Actual live enabled renderers and trail material references. Read-only transient snapshot; stochastic effect timing and inactive renderer branches remain separate."};var stage="Builds/URPMigration/RuntimeRendererAudit-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ");Directory.CreateDirectory(stage);File.WriteAllText(stage+"/report.json",report.ToString());return stage+"/report.json";}
}
